sys_script_include.script:
var CancelEventTaskUtils = Class.create();
CancelEventTaskUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	cancelTask: function() {
		var _recordSysId = this.getParameter('sysparm_sys_id');

		var _taskGR = new GlideRecord('x_1790139_event_ma_event_task');
		if(_taskGR.get(_recordSysId)) {
			_taskGR.x_status = 'cancelled';
			_taskGR.update();

			gs.eventQueue('x_1790139_event_ma.task.cancel', _taskGR, _taskGR.assigned_to.email, '');	
		}
	},

    type: 'CancelEventTaskUtils'
});
